__global__ void scaled_dot_product_attention_kernel(
    const half* __restrict__ Q,
    const half* __restrict__ K,
    const half* __restrict__ V,
    half* __restrict__ output,
    int batch_size,
    int num_heads,
    int sequence_length,
    int embedding_dimension
) {
    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) return;

    const int stride_q = sequence_length * embedding_dimension;
    const int stride_k = sequence_length * embedding_dimension;
    const int stride_v = sequence_length * embedding_dimension;
    const int stride_out = sequence_length * embedding_dimension;

    const int q_offset = batch_idx * stride_q + head_idx * sequence_length * embedding_dimension;
    const int k_offset = batch_idx * stride_k + head_idx * sequence_length * embedding_dimension;
    const int v_offset = batch_idx * stride_v + head_idx * sequence_length * embedding_dimension;
    const int out_offset = batch_idx * stride_out + head_idx * sequence_length * embedding_dimension;

    const float scale = 1.0f / sqrtf(static_cast<float>(embedding_dimension));

    // Process each query position
    for (int i = threadIdx.x; i < sequence_length; i += blockDim.x) {
        // For each query position, compute attention over all key positions
        half* out_row = output + out_offset + i * embedding_dimension;

        // Compute attention weights for this query position
        float max_val = -1e38f;
        float sum_val = 0.0f;
        float weights[512]; // Assuming max sequence length is 512

        // Compute dot products and find max for numerical stability
        for (int j = 0; j < sequence_length; j++) {
            float sum = 0.0f;
            for (int k = 0; k < embedding_dimension; k++) {
                float q_val = __half2float(Q[q_offset + i * embedding_dimension + k]);
                float k_val = __half2float(K[k_offset + j * embedding_dimension + k]);
                sum += q_val * k_val;
            }
            sum *= scale;
            weights[j] = sum;
            max_val = fmaxf(max_val, sum);
        }

        // Compute exp(weights - max_val) and sum
        float exp_sum = 0.0f;
        for (int j = 0; j < sequence_length; j++) {
            weights[j] = expf(weights[j] - max_val);
            exp_sum += weights[j];
        }

        // Normalize and compute output vector
        for (int k = 0; k < embedding_dimension; k++) {
            float sum = 0.0f;
            for (int j = 0; j < sequence_length; j++) {
                float weight = weights[j] / exp_sum;
                float v_val = __half2float(V[v_offset + j * embedding_dimension + k]);
                sum += weight * v_val;
            }
            out_row[k] = __float2half(sum);
        }
    }
}

// Wrapper function to launch kernel
extern "C" void launch_scaled_dot_product_attention(
    const half* Q,
    const half* K,
    const half* V,
    half* output,
    int batch_size,
    int num_heads,
    int sequence_length,
    int embedding_dimension
) {
    dim3 grid(batch_size, num_heads);
    dim3 block(min(512, sequence_length)); // Limit block size

    scaled_dot_product_attention_kernel<<<grid, block>>>(
        Q, K, V, output, batch_size, num_heads, sequence_length, embedding_dimension
    );

    cudaDeviceSynchronize();
}
